var s=UnityEngine.Object.FindFirstObjectByType<ChooGuard.App.Mvp.MvpStationView>();var rows=new System.Collections.Generic.List<object>();for(int i=0;i<3;i++){var f=s.FloorRoots[i];string name=i==2?"안내도 기반 식당가와 발코니":"공개 외곽 기반 바닥";var m=f.Find(name).GetComponent<UnityEngine.MeshFilter>().sharedMesh;var r=f.Find(name).GetComponent<UnityEngine.Renderer>();double area=0;bool up=true;var v=m.vertices;var t=m.GetTriangles(0);for(int j=0;j<t.Length;j+=3){var n=UnityEngine.Vector3.Cross(v[t[j+1]]-v[t[j]],v[t[j+2]]-v[t[j]]);area+=n.magnitude*.5;up&=n.y>0;}rows.Add(new{floor=i+1,vertices=m.vertexCount,uv=m.uv.Length,thickness=m.bounds.size.y,top=m.bounds.max.y,bottom=m.bounds.min.y,topArea=area,upward=up,materials=System.Array.ConvertAll(r.sharedMaterials,x=>x.name),texture=r.sharedMaterials[0].mainTexture.name});}return rows.ToArray();